	if err != nil {
		base = EntireSettingsFile // Fallback to relative
	}
	local, err = paths.AbsPath(ctx, EntireSettingsLocalFile)
	if err != nil {
		local = EntireSettingsLocalFile // Fallback to relative
	}
	return base, local
}

